// Seanime serializes this callback into a separate UI runtime.
$ui.register(function (ctx) {
  // Shared by the Seanime payload builder and tests. No GPU acceleration is claimed.
const FILTER_LABEL = "frameboost";
const presets = {
  motion: {
    fps: 60,
    name: "60 FPS motion interpolation (experimental)",
    graph: "minterpolate=fps=60:mi_mode=mci:mc_mode=obmc:me_mode=bilat:me=epzs:vsbmc=0",
    description: "Generates motion frames using CPU processing. Start with 720p; 1080p may stutter. Requires the bundled minterpolate filter.",
  },
  blend: {
    fps: 60,
    name: "60 FPS frame blending",
    graph: "minterpolate=fps=60:mi_mode=blend",
    description: "Blends adjacent frames. Lower processing cost, but can cause ghosting; does not estimate motion.",
  },
  blend144: {
    fps: 144,
    name: "144 FPS frame blending (experimental)",
    graph: "minterpolate=fps=144:mi_mode=blend",
    description: "Targets a 144 Hz screen using frame blending. Does not generate motion detail. More output frames can increase drops; compare a fresh playback session with 60 FPS.",
  },
  motion144: {
    fps: 144,
    name: "144 FPS motion interpolation (heavy CPU load)",
    graph: "minterpolate=fps=144:mi_mode=mci:mc_mode=obmc:me_mode=bilat:me=epzs:vsbmc=0",
    description: "Estimates motion for 144 FPS output using CPU processing. Try 720p first. 1080p may not keep up; return to 60 FPS if frames drop or audio drifts.",
  },
};

function getPreset(id) {
  if (!Object.prototype.hasOwnProperty.call(presets, id)) throw new Error("Unknown FrameBoost preset");
  return presets[id];
}

function filterSpec(id) {
  return "@" + FILTER_LABEL + ":lavfi=[" + getPreset(id).graph + "]";
}

function configFor(id) {
  return "# FrameBoost: " + getPreset(id).name + "\n"
    + "# Remove this block to disable; stop and reopen playback after changing.\n"
    + "hwdec=auto-copy\n"
    + "vf-add=" + filterSpec(id) + "\n";
}

  var selected = ctx.fieldRef("motion");
  var config = ctx.fieldRef(configFor("motion"));
  var status = "Built-in MpvCore: use Custom MPV Options. HTML5 VideoCore requires the custom Denshi build.";
  var tray = ctx.newTray({
    iconUrl: "https://raw.githubusercontent.com/DefnoJae/FrameBoost/main/assets/icon.svg",
    withContent: true,
    width: "430px",
  });

  function fail(error) {
    status = "FrameBoost: " + (error && error.message ? error.message : String(error));
    ctx.toast.error(status);
    tray.update();
  }

  function connection() {
    var conn = ctx.mpv.getConnection();
    if (!conn || conn.isClosed()) {
      throw new Error("No external MPV connection. For built-in MpvCore, use the configuration below.");
    }
    return conn;
  }

  function hasFilter(conn) {
    var filters = conn.get("vf");
    if (!Array.isArray(filters)) throw new Error("Could not read MPV filters; no change made.");
    return filters.some(function (item) { return item.label === FILTER_LABEL; });
  }

  selected.onValueChange(function (id) {
    config.setValue(configFor(id));
    tray.update();
  });

  var enable = ctx.eventHandler("frameboost-enable", function () {
    try {
      var conn = connection();
      // Do not replace the existing vf chain, decoder, speed, or sync options.
      if (hasFilter(conn)) throw new Error("FrameBoost is already attached. Disable it before changing presets.");
      conn.call("vf", "add", filterSpec(selected.current));
      if (!hasFilter(conn)) throw new Error("MPV did not attach the filter. Check its logs for minterpolate support.");
      status = "FrameBoost filter attached to external MPV. Target: " + getPreset(selected.current).fps + " FPS; real-time performance is not verified.";
      ctx.toast.info(status);
      tray.update();
    } catch (error) { fail(error); }
  });

  var disable = ctx.eventHandler("frameboost-disable", function () {
    try {
      var conn = connection();
      if (hasFilter(conn)) conn.call("vf", "remove", "@" + FILTER_LABEL);
      if (hasFilter(conn)) throw new Error("MPV did not remove the FrameBoost filter.");
      status = "FrameBoost is off in external MPV. Other filters were preserved.";
      ctx.toast.info(status);
      tray.update();
    } catch (error) { fail(error); }
  });

  var settings = ctx.eventHandler("frameboost-settings", function () {
    ctx.screen.navigateTo("/settings", { tab: "playback" });
    tray.close();
  });

  tray.onOpen(function () { tray.update(); });

  tray.render(function () {
    var external = ctx.mpv.getConnection();
    var externalConnected = !!external && !external.isClosed();
    // Component factories return descriptors; render must return their tree.
    return tray.stack({ gap: 3, items: [
      tray.text("FrameBoost", { style: { fontSize: "20px", fontWeight: "700" } }),
      tray.text("Experimental • Seanime Denshi 3.10.3"),
      tray.text("HTML5 VideoCore: this installed plugin cannot process its frames. HTML5 blending requires a custom Denshi build. These presets apply to MpvCore and external MPV."),
      tray.select({ label: "Preset", fieldRef: selected, options: Object.keys(presets).map(function (id) {
        return { value: id, label: presets[id].name };
      }) }),
      tray.text(getPreset(selected.current).description),
      tray.text("Built-in MpvCore setup"),
      tray.text("Copy this block into Settings → Video Playback → Custom MPV Options, above any [profile] sections. Add it once. Stop and reopen the video. Remove the block to disable."),
      tray.input({ label: "MPV configuration (select and copy)", fieldRef: config, textarea: true }),
      tray.button({ label: "Open playback settings", onClick: settings }),
      tray.text(externalConnected ? "External MPV connected" : "External MPV disconnected — controls unavailable for built-in players"),
      tray.button({ label: "Enable in external MPV", onClick: enable, disabled: !externalConnected }),
      tray.button({ label: "Disable in external MPV", onClick: disable, disabled: !externalConnected }),
      tray.text(status),
    ] });
  });
});
